import pytest


def age_at(born: int, now: int) -> int:
    """Return the number of whole years elapsed from birth year `born` to year `now`.

    Raises ValueError if `now` is strictly before `born`.
    """
    if now < born:
        raise ValueError(f"Current year {now} cannot be before birth year {born}")
    return now - born


def test_age_at_positive() -> None:
    assert age_at(1990, 2024) == 34
    assert age_at(2000, 2001) == 1


def test_age_at_same_year() -> None:
    assert age_at(2024, 2024) == 0


def test_age_at_historical() -> None:
    assert age_at(100, 250) == 150


def test_age_at_future_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)

